//! Re-implementation of the small subset of the C++ `indicators` library
//! used by test7: `ProgressDisplay` and `Percentage`.

/// Displays progress as a percentage of a total.
pub struct ProgressDisplay {
    total: i64,
    current: i64,
}

impl ProgressDisplay {
    pub fn new(total: i64) -> Self {
        ProgressDisplay { total, current: 0 }
    }

    /// Set the current progress to an absolute value.
    pub fn update(&mut self, progress: i64) {
        self.current = progress;
    }

    /// Add to the current progress.
    pub fn increment(&mut self, amount: i64) {
        self.current += amount;
    }

    /// Render as `Progress: X.X% (current/total)`.
    pub fn display(&self) -> String {
        let pct = self.current as f64 / self.total as f64 * 100.0;
        format!("Progress: {:.1}% ({}/{})", pct, self.current, self.total)
    }
}

/// A floating-point value rendered as a percentage with fixed decimals.
pub struct Percentage {
    value: f32,
    decimals: usize,
}

impl Percentage {
    pub fn new(value: f32, decimals: usize) -> Self {
        Percentage { value, decimals }
    }

    /// Render the value multiplied by 100 with the configured precision.
    pub fn str(&self) -> String {
        format!("{:.*}", self.decimals, self.value * 100.0)
    }
}

