mod indicators;

use indicators::{Percentage, ProgressDisplay};

/// Mimic C++ `std::stoi`: skip leading whitespace, accept an optional sign,
/// parse leading digits, ignore the rest. Abort on invalid input, matching
/// the uncaught `std::invalid_argument` behavior of the original binary.
fn stoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_whitespace() {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    if i >= b.len() || !b[i].is_ascii_digit() {
        std::process::abort();
    }
    let mut v: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        v = v * 10 + (b[i] - b'0') as i64;
        i += 1;
    }
    (sign * v) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let progress: i32 = if args.len() > 1 {
        stoi(&args[1])
    } else {
        150
    };

    let mut display = ProgressDisplay::new(200);
    display.update(progress as i64);
    println!("{}", display.display());

    display.increment(25);
    println!("{}", display.display());

    let pct1 = Percentage::new(0.15, 1);
    let pct2 = Percentage::new(0.35, 2);
    let pct3 = Percentage::new(0.65, 3);
    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", pct3.str());
}

